    lv_obj_clear_flag(s_dot, LV_OBJ_FLAG_SCROLLABLE);

    s_link_lbl = put_label(s_scr, "NO LINK", 104, 10, &lv_font_montserrat_14, C_RED);

    s_batt_lbl = make_label(s_scr, "--", &lv_font_montserrat_14, C_MUTED);
