static void render_ark(void)
{
    bool ok = s_ark.valid && s_ark.err == 0;

    // Title comes from the bridge config (key "t"); fall back to the default.
    // Pick the 40px font when it fits within ARK_TITLE_W_MAX, else drop to
    // 20px (shifted down to stay in the same band above the chips). Pure
    // ASCII titles use the montserrat fonts, CJK ones the app fonts.
    const char *title = s_ark.title[0] ? s_ark.title : "Coding Plan";
    bool ascii = true;
    for (const char *q = title; *q; q++) {
        if ((unsigned char)*q >= 0x80) {
            ascii = false;
            break;
        }
    }
    // Pick the largest font whose measured width fits the limit. Chinese
    // titles have no 28px subset font, so they fall back 40 -> 20 directly.
    const lv_font_t *cands[3];
    int n = 0;
    if (ascii) {
        cands[n++] = &lv_font_montserrat_40;
        cands[n++] = &lv_font_montserrat_28;
        cands[n++] = &lv_font_montserrat_20;
    } else {
        cands[n++] = &app_font_40;
        cands[n++] = &app_font_20;
    }
    const lv_font_t *font = cands[n - 1];
    for (int i = 0; i < n; i++) {
        lv_point_t size;
        lv_text_get_size(&size, title, cands[i], 0, 0, LV_COORD_MAX,
                         LV_TEXT_FLAG_EXPAND);
        if (size.x <= ARK_TITLE_W_MAX) {
            font = cands[i];
            break;
        }
    }
    // Vertically center the title in the ~46px band above the chips row.
    int title_y = (46 - (int)font->line_height) / 2;
    if (title_y < 0) {
        title_y = 0;
    }
    lv_obj_set_style_text_font(s_ark_title, font, 0);
    lv_obj_set_y(s_ark_title, title_y);
    lv_label_set_text(s_ark_title, title);

    lv_label_set_text(s_ark_plan_chip, s_ark.plan[0] ? s_ark.plan : "--");
    lv_label_set_text(s_ark_name_chip, s_ark.name[0] ? s_ark.name : "--");
    int64_t now = esp_timer_get_time() / 1000;
    long elapsed = s_ark.valid ? (long)((now - s_ark_rx_ms) / 1000) : 0;
    for (int i = 0; i < PCMON_ARK_WINDOWS; i++) {
        bool has = ok && s_ark.has_win[i] && s_ark.quota[i] > 0.0f;
        if (has) {
            float pct = s_ark.used[i] * 100.0f / s_ark.quota[i];
            int v = clamp100(pct);
            lv_bar_set_value(s_ark_bar[i], v, LV_ANIM_OFF);
            lv_obj_set_style_bg_color(s_ark_bar[i],
                lv_color_hex(level_color(pcmon_level(pct))), LV_PART_INDICATOR);
            lv_label_set_text_fmt(s_ark_pct[i], "%d", v);
            long remain = s_ark.reset_s[i] - elapsed;
            if (remain < 0) {
                remain = 0;
            }
            if (remain >= 86400) {
                label_printf(s_ark_reset[i], "%ldd%ldh后重置", remain / 86400,
                             (remain % 86400) / 3600);
            } else if (remain >= 3600) {
                label_printf(s_ark_reset[i], "%ldh%ldm后重置", remain / 3600,
                             (remain % 3600) / 60);
            } else {
                label_printf(s_ark_reset[i], "%ldm后重置", remain / 60);
            }
            label_printf(s_ark_detail[i], "%.0f / %.0f", (double)s_ark.used[i],
                         (double)s_ark.quota[i]);
        } else {
            lv_bar_set_value(s_ark_bar[i], 0, LV_ANIM_OFF);
            lv_label_set_text(s_ark_pct[i], "--");
            lv_label_set_text(s_ark_reset[i], "--");
            const char *msg = "--";
            if (s_ark.valid) {
                if (s_ark.err == 1) {
                    msg = "未配置";
                } else if (s_ark.err == 2) {
                    msg = "获取失败";
                }
            }
            lv_label_set_text(s_ark_detail[i], msg);
        }
    }
}

static void render_trae(void)
{
    int64_t now = esp_timer_get_time() / 1000;
    if (s_view == PCMON_VIEW_TRAE && now - s_av_frame_ms >= 400) {
        s_av_frame_ms = now;
        trae_avatar_next_frame();
    }

    // Memory probe: log once per second while on this page, to catch LVGL
    // pool exhaustion (suspected cause of the white-screen reboot loop).
    static int64_t s_probe_ms;
    if (s_view == PCMON_VIEW_TRAE && now - s_probe_ms >= 1000) {
        s_probe_ms = now;
        lv_mem_monitor_t mon;
        lv_mem_monitor(&mon);
        ESP_LOGI(TAG, "trae page: lv free=%u%% (%u B), heap free=%u",
                 (unsigned)(100 - mon.used_pct), (unsigned)mon.free_size,
                 (unsigned)esp_get_free_heap_size());
    }

    static const char *const st_names[] = {
        "已累瘫", "思考中", "敲代码中", "构建中", "通过", "失败"};
    static const uint32_t st_colors[] = {
        C_MUTED, C_CYAN, C_GREEN, C_AMBER, C_GREEN, C_RED};

    if (!s_trae.valid) {
        trae_avatar_set_state(PCMON_TRAE_IDLE);
        lv_label_set_text(s_trae_chip, "离线");
        lv_obj_set_style_text_color(s_trae_chip, lv_color_hex(C_MUTED), 0);
        lv_obj_set_style_border_color(s_trae_chip_obj, lv_color_hex(C_MUTED), 0);
    } else {
        int st = s_trae.st;
        if (st < PCMON_TRAE_IDLE || st > PCMON_TRAE_FAIL) {
            st = PCMON_TRAE_IDLE;
        }
        trae_avatar_set_state(st);
        lv_label_set_text(s_trae_chip, st_names[st]);
        lv_obj_set_style_text_color(s_trae_chip, lv_color_hex(st_colors[st]), 0);
        lv_obj_set_style_border_color(s_trae_chip_obj,
                                      lv_color_hex(st_colors[st]), 0);
    }

    if (s_trae.has_task) {
        lv_label_set_text_fmt(s_trae_task, "#%ld", s_trae.task);
        lv_obj_set_style_text_color(s_trae_task, lv_color_hex(C_TEXT), 0);
    } else {
        lv_label_set_text(s_trae_task, "--");
        lv_obj_set_style_text_color(s_trae_task, lv_color_hex(C_DIM), 0);
    }
    if (s_trae.has_rate) {
        lv_label_set_text_fmt(s_trae_rate, "%d%%", s_trae.rate);
        lv_bar_set_value(s_trae_rate_bar, clamp100(s_trae.rate), LV_ANIM_OFF);
        lv_obj_set_style_bg_color(s_trae_rate_bar,
            lv_color_hex(level_color(pcmon_level(s_trae.rate))),
            LV_PART_INDICATOR);
    } else {
        lv_label_set_text(s_trae_rate, "--");
        lv_bar_set_value(s_trae_rate_bar, 0, LV_ANIM_OFF);
    }
    if (s_trae.has_cm) {
        lv_label_set_text_fmt(s_trae_cm, "%ld 分钟", s_trae.cm);
    } else {
        lv_label_set_text(s_trae_cm, "--");
    }

    if (s_aprv.valid) {
        // Full-screen review: swap the stat rows for the command box.
        set_hidden(s_trae_aprv_box, false);
        set_hidden(s_trae_stats, true);
        lv_label_set_text_fmt(s_trae_aprv_id, "待审批 #%ld", s_aprv.id);
        lv_label_set_text(s_trae_aprv_cmd, s_aprv.cmd[0] ? s_aprv.cmd : "--");
        // Blink the action hint so an idle badge is obvious from across the desk.
        set_hidden(s_trae_aprv_hint, ((now / 500) & 1) != 0);
    } else {
        set_hidden(s_trae_aprv_box, true);
        set_hidden(s_trae_stats, false);
    }

    // Persistent "last decision" line (was a 2s flash; kept visible now so
    // the bottom of the page always carries some color once a decision lands).
    if (s_aprv_done_ms != 0) {
        lv_label_set_text_fmt(s_trae_feedback, "最近审批 %s #%ld",
                              s_aprv_allow ? "已批准" : "已拒绝", s_aprv_done_id);
        lv_obj_set_style_text_color(s_trae_feedback,
                                    lv_color_hex(s_aprv_allow ? C_GREEN : C_RED), 0);
    } else {
        lv_label_set_text(s_trae_feedback, "最近审批 --");
        lv_obj_set_style_text_color(s_trae_feedback, lv_color_hex(C_MUTED), 0);
    }
}

// Dispatch table so only the visible page's renderer runs; off-page widgets
// don't exist under on-demand building, so their renderers must not touch
// dangling pointers.
typedef void (*page_renderer_t)(void);

static const page_renderer_t s_renderers[PCMON_PAGES] = {
    render_core, render_cpu, render_mem, render_disk, render_net,
    render_trend, render_sys, render_gpu, render_proc, render_port,
    render_ark, render_trae, render_agent,
};

static void render(void)
{
    if (!s_scr) {
        return;
    }

    page_show(s_view);
    lv_label_set_text(s_title, PAGE_NAMES[s_view]);

    int64_t now = esp_timer_get_time() / 1000;
    if (s_stats.valid && (now - s_last_rx_ms) < PCMON_FRESH_MS) {
        lv_obj_set_style_bg_color(s_dot, lv_color_hex(C_GREEN), 0);
        lv_label_set_text(s_link_lbl, "LINK");
        lv_obj_set_style_text_color(s_link_lbl, lv_color_hex(C_GREEN), 0);
    } else if (s_stats.valid) {
        lv_obj_set_style_bg_color(s_dot, lv_color_hex(C_AMBER), 0);
        lv_label_set_text(s_link_lbl, "STALE");
        lv_obj_set_style_text_color(s_link_lbl, lv_color_hex(C_AMBER), 0);
    } else {
        lv_obj_set_style_bg_color(s_dot, lv_color_hex(C_RED), 0);
        lv_label_set_text(s_link_lbl, "NO LINK");
        lv_obj_set_style_text_color(s_link_lbl, lv_color_hex(C_RED), 0);
    }

    if (s_batt_pct < 0) {
        lv_label_set_text(s_batt_lbl, "--");
        lv_obj_set_style_text_color(s_batt_lbl, lv_color_hex(C_MUTED), 0);
    } else {
        uint32_t c = s_batt_pct > 50 ? C_GREEN : (s_batt_pct > 20 ? C_AMBER : C_RED);
        lv_label_set_text_fmt(s_batt_lbl, "%d%%", s_batt_pct);
        lv_obj_set_style_text_color(s_batt_lbl, lv_color_hex(c), 0);
    }

    if (s_paused) {
        lv_label_set_text(s_hint, "PAUSED  OK:req  HOLD:resume");
    } else if (s_view == PCMON_VIEW_TRAE && s_aprv.valid) {
        lv_label_set_text(s_hint, "UP/DN page  OK:allow  HOLD:deny");
    } else if (s_view == PCMON_VIEW_PROC) {
        lv_label_set_text(s_hint, "UP/DN page  OK:sort  HOLD:pause");
    } else {
        lv_label_set_text(s_hint, "UP/DN page  OK:req  HOLD:pause");
    }

    s_renderers[s_view]();
}

static void hist_push(int v)
{
    for (int i = 0; i < PCMON_HIST - 1; i++) {
        s_hist_vals[i] = s_hist_vals[i + 1];
    }
    s_hist_vals[PCMON_HIST - 1] = v;
}

static void on_line(const char *line, void *user)
{
    (void)user;
    if (!s_queue) {
        return;
    }
    pcmon_ev_t ev;
    memset(&ev, 0, sizeof(ev));
    ev.kind = PCMON_EV_LINE;
    strncpy(ev.line, line, sizeof(ev.line) - 1);
    (void)xQueueSend(s_queue, &ev, 0);
}

static void on_btn(bsp_btn_t btn, bsp_btn_ev_t bev, void *user)
{
    (void)user;
    if (!s_queue) {
        return;
    }
    pcmon_ev_t ev;
    memset(&ev, 0, sizeof(ev));
    ev.kind = PCMON_EV_BTN;
    ev.btn = btn;
    ev.bev = bev;
    (void)xQueueSend(s_queue, &ev, 0);
}

static void request_now(void)
{
    const char *need = NULL;
    if (s_view == PCMON_VIEW_GPU) {
        need = PCMON_NEED_GPU;
    } else if (s_view == PCMON_VIEW_PROC) {
        need = PCMON_NEED_PROC;
    } else if (s_view == PCMON_VIEW_PORT) {
        need = PCMON_NEED_PORT;
    } else if (s_view == PCMON_VIEW_ARK) {
        need = PCMON_NEED_ARK;
    }
    char req[40];
    if (pcmon_format_request(req, sizeof(req), need, s_proc_sort) > 0) {
        pcmon_link_send(req);
        s_tx_frames++;
    }
}

// Sends the badge's decision for the pending approval and swaps the overlay
// for a short "已批准/已拒绝" feedback. The bridge clears its pending queue
// on $TBTN, so the $TAPRV stream stops with this id.
static void send_trae_decision(bool allow)
{
    char out[48];
    if (pcmon_format_trae_btn(s_aprv.id, allow, out, sizeof(out)) > 0) {
        pcmon_link_send(out);
        s_tx_frames++;
    }
    s_aprv_allow = allow;
    s_aprv_done_id = s_aprv.id;
    s_aprv_done_ms = esp_timer_get_time() / 1000;
    pcmon_trae_aprv_reset(&s_aprv);
    ESP_LOGI(TAG, "trae approval #%ld %s", s_aprv_done_id, allow ? "allow" : "deny");
}

static bool handle_event(const pcmon_ev_t *ev)
{
    if (ev->kind == PCMON_EV_LINE) {
        pcmon_agent_t agent;
        if (pcmon_parse_agent(ev->line, &agent)) {
            s_agent = agent;
            s_last_agent_ms = esp_timer_get_time() / 1000;
            return true;
        }

        pcmon_gpu_t gpu;
        if (pcmon_parse_gpu(ev->line, &gpu)) {
            s_gpu = gpu;
            s_rx_frames++;
            return true;
        }

        pcmon_proc_list_t procs;
        if (pcmon_parse_proc_list(ev->line, &procs)) {
            s_proc_list = procs;
            s_rx_frames++;
            return true;
        }

        pcmon_port_list_t ports;
        if (pcmon_parse_port_list(ev->line, &ports)) {
            s_port_list = ports;
            s_rx_frames++;
            return true;
        }

        pcmon_ark_t ark;
        if (pcmon_parse_ark(ev->line, &ark)) {
            s_ark = ark;
            s_ark_rx_ms = esp_timer_get_time() / 1000;
            s_rx_frames++;
            return true;
        }

        pcmon_trae_t trae;
        if (pcmon_parse_trae(ev->line, &trae)) {
            s_trae = trae;
            return true;
        }

        pcmon_trae_aprv_t aprv;
        if (pcmon_parse_trae_aprv(ev->line, &aprv)) {
            if (aprv.id != s_aprv_skip_id &&
                (!s_aprv.valid || aprv.id != s_aprv.id)) {
                // New pending command: show it and jump to the battle page.
                s_aprv = aprv;
                s_aprv_rx_ms = esp_timer_get_time() / 1000;
                if (s_view != PCMON_VIEW_TRAE) {
                    s_view = PCMON_VIEW_TRAE;
                }
            }
            return true;
        }

        pcmon_stats_t parsed;
        if (pcmon_parse_status(ev->line, &parsed)) {
            bool new_sample = !s_stats.valid || parsed.cpu != s_stats.cpu ||
                              parsed.mem != s_stats.mem || parsed.uptime_s != s_stats.uptime_s ||
                              parsed.has_uptime != s_stats.has_uptime;
            s_stats = parsed;
            s_last_rx_ms = esp_timer_get_time() / 1000;
            s_last_agent_ms = s_last_rx_ms;
            s_rx_frames++;
            if (new_sample && s_stats.has_cpu) {
                hist_push(clamp100(s_stats.cpu));
            }
            return true;
        }
        return false;
    }

    if (ev->bev == BSP_BTN_CLICK) {
        if (ev->btn == BSP_BTN_UP) {
            s_view = (s_view + PCMON_PAGES - 1) % PCMON_PAGES;
            return true;
        }
        if (ev->btn == BSP_BTN_DOWN) {
            s_view = (s_view + 1) % PCMON_PAGES;
            return true;
        }
        if (ev->btn == BSP_BTN_OK) {
            if (s_view == PCMON_VIEW_TRAE && s_aprv.valid) {
                send_trae_decision(true);
                return true;
            }
            if (s_view == PCMON_VIEW_PROC) {
                s_proc_sort = s_proc_sort ? 0 : 1;
            }
            request_now();
            return true;
        }
    }
    if (ev->bev == BSP_BTN_LONG && ev->btn == BSP_BTN_OK) {
        if (s_view == PCMON_VIEW_TRAE && s_aprv.valid) {
            // Long OK cancels the pending RunCommand.
            send_trae_decision(false);
            return true;
        }
        s_paused = !s_paused;
        ESP_LOGI(TAG, "auto poll %s", s_paused ? "paused" : "resumed");
        return true;
    }
    return false;
}

static void app_task(void *arg)
{
    (void)arg;
    int64_t last_req = 0;
    int64_t last_batt = 0;
    int64_t last_tick = 0;

    for (;;) {
        int64_t now = esp_timer_get_time() / 1000;

        if (!s_paused && now - last_req >= PCMON_POLL_MS) {
            request_now();
            last_req = now;
        }

        if (now - last_batt >= PCMON_BATT_MS) {
            s_batt_pct = bsp_battery_soc();
            last_batt = now;
        }

        pcmon_ev_t ev;
        bool changed = false;
        if (xQueueReceive(s_queue, &ev, pdMS_TO_TICKS(50)) == pdTRUE) {
            changed = handle_event(&ev);
        }

        // Drop a pending approval once its hook could no longer be waiting.
        if (s_aprv.valid && now - s_aprv_rx_ms >= PCMON_APRV_TTL_MS) {
            s_aprv_skip_id = s_aprv.id;
            pcmon_trae_aprv_reset(&s_aprv);
            changed = true;
        }

        // Faster tick while the battle page animates or an approval blinks.
        int tick_ms = (s_aprv.valid || s_view == PCMON_VIEW_TRAE) ? 500 : 1000;
        if (changed || now - last_tick >= tick_ms) {
            last_tick = now;
            if (bsp_lvgl_lock(200)) {
                render();
                bsp_lvgl_unlock();
            }
        }
    }
}

bool app_pcmon_start(void)
{
    pcmon_stats_reset(&s_stats);
    memset(&s_agent, 0, sizeof(s_agent));
    pcmon_proc_list_reset(&s_proc_list);
    pcmon_port_list_reset(&s_port_list);
    pcmon_gpu_reset(&s_gpu);
    pcmon_ark_reset(&s_ark);
    pcmon_trae_reset(&s_trae);
    pcmon_trae_aprv_reset(&s_aprv);
    s_aprv_done_ms = 0;
    s_aprv_skip_id = 0;
    s_proc_sort = 0;
    s_last_rx_ms = esp_timer_get_time() / 1000;
    s_last_agent_ms = s_last_rx_ms;
    s_ark_rx_ms = s_last_rx_ms;

    s_queue = xQueueCreate(PCMON_EVENT_DEPTH, sizeof(pcmon_ev_t));
    if (!s_queue) {
        ESP_LOGE(TAG, "event queue alloc failed");
        return false;
    }

    if (!pcmon_link_init(on_line, NULL)) {
        ESP_LOGE(TAG, "link init failed");
        return false;
    }

    if (bsp_button_init(on_btn, NULL) != ESP_OK) {
        ESP_LOGW(TAG, "button init failed; navigation disabled");
    }

    if (bsp_lvgl_lock(1000)) {
        build_ui();
        bsp_lvgl_unlock();
    } else {
        ESP_LOGE(TAG, "LVGL lock failed during UI build");
        return false;
    }

    ESP_LOGI(TAG, "UI built, free heap %u bytes", (unsigned)esp_get_free_heap_size());

    if (xTaskCreate(app_task, "pcmon_app", 6144, NULL, 5, NULL) != pdPASS) {
        ESP_LOGE(TAG, "app task create failed");
        return false;
    }

    ESP_LOGI(TAG, "PC monitor ready");
    return true;
}
